'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(Number(n)||0);
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
const stamp=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const uid=()=>crypto.randomUUID();
const icon=(name)=>{const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',video:'M3 5h13v14H3z M16 10l5-3v10l-5-3',mentor:'M12 3a7 7 0 0 0-4 13v3h8v-3a7 7 0 0 0-4-13 M9 22h6',niche:'M12 3 3 8l9 5 9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',shield:'M12 3 20 6v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',chart:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17v-9',coin:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9 M12 6v12',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',check:'M5 12l4 4L19 6',plus:'M12 4v16 M4 12h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3z M12 6v15',menu:'M3 6h18 M3 12h18 M3 18h18',download:'M12 3v13 M7 11l5 5 5-5 M3 18v3h18v-3'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.video}"/></svg>`};
let data={state:{},media:[],jobs:[],mentor:{},capabilities:{}},research={sources:[],niches:[]},route='dashboard',selected=null,subtab='edit',busy=false;
const pages=[['dashboard','home','Ringkasan'],['studio','video','Studio klip'],['mentor','mentor','Mentor channel'],['niches','niche','Niche & pasar'],['sources','shield','Sumber & izin'],['calendar','calendar','Kalender konten'],['analytics','chart','Evaluasi'],['monetization','coin','Monetisasi'],['research','book','Dasar riset'],['settings','settings','Pengaturan']];
const state=(key,def)=>data.state[key]??def;
async function api(path,body){const opt=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-ViraClip':'1'},body:JSON.stringify(body)};const r=await fetch('/api/'+path,opt);const t=await r.text();let v;try{v=JSON.parse(t)}catch{v={error:'Respons server tidak terbaca.'}}if(!r.ok){if(r.status===401&&path!=='login')login();throw Error(v.error||'Permintaan gagal')}return v;}
async function save(key,value){await api('state',{key,value});data.state[key]=value;}
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',5000);}
async function refresh(){data=await api('bootstrap');if(!selected&&data.media.some(m=>m.width))selected=data.media.find(m=>m.width).id;}
function heading(title,sub,button=''){return `<div class="page-heading"><div><div class="eyebrow">Ruang kerja kreator</div><h1>${title}</h1><p class="sub">${sub}</p></div>${button}</div>`;}
function empty(title,sub,button=''){return `<div class="empty">${icon('video')}<h3>${title}</h3><p>${sub}</p>${button}</div>`;}
function btn(text,action,cl='primary',attrs=''){return `<button class="${cl}" data-action="${action}" ${attrs}>${text}</button>`;}
function field(label,name,value='',type='text',attrs=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,options,current){return `<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(current)===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function area(label,name,value='',attrs=''){return `<label class="field">${label}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;}
function modal(title,content){$('#modal').innerHTML=`<button class="small close" data-action="close-modal" aria-label="Tutup">✕</button><h2>${title}</h2>${content}`;$('#modal').showModal();}
function navigate(name){if(!pages.some(p=>p[0]===name))name='dashboard';route=name;location.hash=name;render();window.scrollTo(0,0);}
function render(){const profile=state('profile',{});$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt="">ViraClip<small>STUDIO</small></div><button class="mobile-nav-close small section-space" data-action="menu">Tutup menu</button><div class="nav-label">Workspace</div><nav class="nav" aria-label="Navigasi utama">${pages.slice(0,8).map(([id,i,l])=>`<button data-nav="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav><div class="nav-label">Pengetahuan & akun</div><nav class="nav">${pages.slice(8).map(([id,i,l])=>`<button data-nav="${id}" class="${route===id?'active':''}">${icon(i)}${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="account"><span class="avatar">${esc((profile.name||'K').slice(0,1).toUpperCase())}</span><div><strong>${esc(profile.name||'Kreator baru')}</strong><small>Ruang kerja pribadi</small></div></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="menu-toggle small" data-action="menu" aria-label="Buka menu">☰</button><span>Workspace / <span style="color:var(--text)">${pages.find(p=>p[0]===route)?.[2]}</span></span></div><div class="right"><span>${new Date().toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}</span><span class="badge lime">Data tersimpan di server</span></div></header><div id="view">${views[route]()}</div><p class="footer-note">ViraClip · Dibangun untuk proses yang terukur. Pendapatan dan persetujuan monetisasi bergantung pada hasil serta peninjauan YouTube.</p></main></div>`;}
const TASKS=[['profile','Tentukan arah channel','Pilih bahasa, niche, dan waktu produksi yang realistis.','15 mnt','mentor'],['channel','Siapkan identitas channel','Buat nama, deskripsi, foto profil, dan aktifkan verifikasi dua langkah.','25 mnt','mentor'],['source','Pastikan hak sumber video','Gunakan rekaman sendiri atau catat bukti izin komersial.','15 mnt','sources'],['idea','Pilih satu masalah penonton','Tulis pertanyaan penonton dan jawaban yang dapat didemonstrasikan.','15 mnt','niches'],['original','Tulis kontribusi orisinal','Tambahkan pengalaman, demonstrasi, analisis, atau contoh Anda sendiri.','25 mnt','mentor'],['clip','Produksi klip pertama','Unggah, potong, koreksi subtitle, lalu periksa hasil ekspor.','30 mnt','studio'],['publish','Publikasikan dengan konteks','Judul sesuai isi, atribusi jika diperlukan, dan deskripsi yang jelas.','15 mnt','calendar'],['review','Catat hasil setelah 48 jam','Isi metrik dari YouTube Studio dan catat hal yang akan diperbaiki.','15 mnt','analytics']];
function tasklist(limit=8){const done=state('tasks',{});return TASKS.slice(0,limit).map(([id,title,desc,t,nav])=>`<label class="task ${done[id]?'done':''}"><input type="checkbox" data-task="${id}" ${done[id]?'checked':''}><div><strong>${title}</strong><p>${desc} <a href="#${nav}">Buka</a></p></div><span class="time">${t}</span></label>`).join('');}
function dashboard(){const p=state('profile',{}),m=state('monetization',{}),done=TASKS.filter(t=>state('tasks',{})[t[0]]).length,exports=Object.keys(data.state).filter(k=>k.startsWith('export:'));return `${heading(`Selamat datang${p.name?', '+esc(p.name):', Kreator'}.`,'Satu langkah yang jelas. Satu konten yang lebih baik.',btn('+ Buat klip','go-studio'))}<div class="grid four"><div class="card stat"><span class="iconbox">${icon('video')}</span><span>Klip selesai</span><strong>${exports.length}</strong><p class="sub">Hasil ekspor Anda</p></div><div class="card stat"><span class="iconbox">${icon('check')}</span><span>Langkah awal</span><strong>${done}<span> / 8</span></strong><p class="sub">Tugas yang ditandai selesai</p></div><div class="card stat"><span class="iconbox">${icon('chart')}</span><span>Subscriber</span><strong>${fmt(m.subscribers||0)}</strong><p class="sub">${m.updated?'Dicatat '+new Date(m.updated).toLocaleDateString('id-ID'):'Belum ada catatan channel'}</p></div><div class="card stat"><span class="iconbox">${icon('coin')}</span><span>Pendapatan tercatat</span><strong style="font-size:1.45rem">${money(state('metrics',[]).reduce((a,v)=>a+Number(v.revenue||0),0))}</strong><p class="sub">Dari catatan konten Anda</p></div></div><div class="grid split section-space"><div><section class="card hero-card"><div class="eyebrow">Langkah berikutnya</div><h2>${p.niche?'Ubah satu ide menjadi konten yang berguna.':'Bangun channel dengan arah yang jelas.'}</h2><p>${p.niche?'Tunjukkan apa yang Anda tambahkan: contoh nyata, penjelasan, atau sudut pandang sendiri.':'Mulai dari kemampuan Anda, pilih masalah penonton, lalu buat rencana produksi yang bisa dijalankan.'}</p><div class="row">${btn(p.niche?'Buka mentor channel':'Susun rencana saya','go-mentor')}<span class="badge">Tanpa janji viral</span></div><span class="hero-mark">VC</span></section><section class="card section-space"><div class="card-header"><h2>Langkah membangun channel</h2><span class="badge lime">${done}/8 selesai</span></div><div class="progress"><i style="width:${done/8*100}%"></i></div>${tasklist(5)}<button class="ghost small section-space" data-nav="mentor">Lihat seluruh tugas</button></section></div><div><section class="card"><div class="card-header"><h2>Rencana uji Anda</h2>${icon('clock')}</div><span class="badge amber">Hipotesis · 14 hari</span><h3 class="section-space">${esc(data.mentor.cadence||'Sesuaikan waktu produksi')}</h3><p class="sub">${esc(data.mentor.market||'Tentukan pasar awal di mentor.')}</p><div class="note">Jam unggah awal adalah bahan uji. Setelah memiliki data, pertahankan yang membantu penonton dan realistis untuk Anda.</div><button class="ghost small section-space" data-nav="calendar">Buka kalender</button></section><section class="card section-space"><h2>Proyek terbaru</h2>${data.media.filter(m=>m.width).length?data.media.filter(m=>m.width).slice(0,3).map(m=>`<div class="media-item"><div class="iconbox">${icon('video')}</div><div><div class="name">${esc(m.name)}</div><small>${stamp(m.duration)} · ${m.width} × ${m.height}</small></div><button class="small" data-open-media="${m.id}">Buka</button></div>`).join(''):empty('Belum ada video','Unggah rekaman pertama untuk mulai membuat klip.',btn('Unggah video','go-studio','small'))}</section></div></div>`;}
function joblist(){return data.jobs.slice(0,5).map(j=>`<div class="calendar-day"><div class="row between"><strong>${({render:'Ekspor video',transcribe:'Transkripsi audio',youtube:'Caption YouTube',analyze:'Analisis poin bernilai',coach:'Coach AI','youtube-video':'Berkas YouTube'})[j.kind]||'Proses'}</strong><span class="badge ${j.status==='error'?'red':j.status==='done'?'lime':''}">${esc(j.status)}</span></div><p class="sub section-space">${esc(j.message)}</p><div class="progress"><i style="width:${j.progress}%"></i></div></div>`).join('')||'<p class="sub">Belum ada proses. Video diproses satu per satu.</p>';}
function exportsView(){const items=Object.entries(data.state).filter(([k])=>k.startsWith('export:')).map(([,v])=>v).sort((a,b)=>b.created-a.created);return items.length?items.map(v=>`<div class="export-item"><video src="${esc(v.video)}" preload="metadata" muted></video><div class="grow"><h3>${esc(v.name)}</h3><p class="sub">${stamp(v.duration)} · MP4</p></div><a class="chip" href="${esc(v.video)}" download>Unduh MP4</a><a class="chip" href="${esc(v.subtitle)}" download>Unduh SRT</a></div>`).join(''):empty('Hasil Anda akan muncul di sini','Ekspor klip pertama, kemudian unduh dan periksa sebelum mengunggah ke YouTube.');}
function mentorLegacy(){const p=state('profile',{});return `<h2>Profil & fondasi channel</h2><div class="grid split"><div><div class="card"><h2>Arah channel Anda</h2><form id="profile-form"><div class="formgrid">${field('Nama Anda','name',p.name||'','text','maxlength="60"')}${field('Nama channel','channel',p.channel||'','text','maxlength="100"')}${select('Bahasa produksi utama','language',[['id','Bahasa Indonesia'],['en','Bahasa Inggris']],p.language||'id')}${select('Waktu produksi per hari','minutes',[[30,'30 menit'],[60,'60 menit'],[120,'2 jam'],[180,'3 jam']],p.minutes||60)}${field('Niche pilihan Anda','niche',p.niche||'','text','placeholder="Boleh kosong; minta coach membantu memilih" maxlength="180"')}${field('Batas biaya bulanan (Rp)','budget',p.budget??0,'number','min="0" max="100000000"')}${area('Keterampilan atau akses yang Anda miliki','skills',p.skills||'','maxlength="1200"')}</div><button class="primary" type="submit">Simpan & susun rencana</button></form></div><div class="card section-space"><h2>Rencana 14 hari pertama</h2><div class="steps"><div class="step active">Hari 1–2<br>Fondasi & sumber</div><div class="step">Hari 3–7<br>Produksi & catat</div><div class="step">Hari 8–13<br>Uji satu variasi</div><div class="step">Hari 14<br>Evaluasi</div></div><div class="note">${esc(data.mentor.cadence)}. Ini kapasitas awal yang disarankan, bukan kewajiban YouTube. Turunkan frekuensi jika kualitas atau waktu keluarga terganggu.</div><p class="sub section-space">${esc(data.mentor.next)}</p>${tasklist()}</div></div><div><div class="card"><span class="badge lime">Rekomendasi mentor</span><h2 class="section-space">Mulai dari keunggulan Anda</h2><p class="sub">${esc(data.mentor.strategy)}</p><p class="sub"><strong>Pasar awal:</strong> ${esc(data.mentor.market)}</p><p class="sub"><strong>Evaluasi:</strong> ${esc(data.mentor.recommendation)}</p></div><div class="card section-space"><h2>Susun paket publikasi</h2><p class="sub">Isi fakta konten Anda. Asisten menyusun draf judul, deskripsi, dan narasi dengan pola editorial; bukan mesin prediksi viral.</p><form id="copy-form">${field('Topik / masalah penonton','topic','','text','required maxlength="180" placeholder="Contoh: Merapikan tabel Excel"')}${area('Solusi atau temuan yang benar-benar Anda tunjukkan','takeaway','','required maxlength="1000"')}${field('Sumber / bukti (opsional)','evidence','','text','maxlength="300"')}<label class="checkrow"><input type="checkbox" name="hashtags" checked>Sertakan 2–3 hashtag yang relevan</label><button class="primary" type="submit">Buat draf publikasi</button></form></div></div></div>`;}
function niches(){const p=state('profile',{});return `${heading('Niche & pasar','Pilih yang dapat Anda produksi dengan baik, lalu validasi permintaannya.')}<div class="note">Kartu berikut adalah hipotesis awal berdasarkan kemudahan produksi dan orisinalitas, bukan peringkat RPM atau tren langsung. Jangan memilih negara hanya dari klaim tarif iklan.</div><div class="grid two section-space">${research.niches.map((n,i)=>`<article class="card niche"><div class="row between"><span class="niche-number">0${i+1} / ARAH KONTEN</span><span class="badge ${p.niche===n.id?'lime':''}">${p.niche===n.id?'Pilihan Anda':n.tag}</span></div><h3>${n.name}</h3><p class="sub">${n.fit}</p><div class="row"><span class="chip">Produksi ${n.effort.toLowerCase()}</span><span class="chip">Hipotesis</span></div><p class="idea">${n.idea}</p><p class="sub"><strong>Alasan:</strong> ${n.reason}</p><p class="sub"><strong>Pasar:</strong> ${n.market}</p><p class="sub"><strong>Perhatian:</strong> ${n.risk}</p><div class="row"><button class="${p.niche===n.id?'ghost':'primary'} small" data-pick-niche="${n.id}">${p.niche===n.id?'Dipilih':'Pilih niche'}</button><a class="chip" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query=${encodeURIComponent(n.keywords.join(' '))}">Riset contoh di YouTube</a></div></article>`).join('')}</div><div class="card section-space"><h2>Bandingkan pasar secara terukur</h2><div class="table-wrap"><table><thead><tr><th>Pasar uji</th><th>Keuntungan praktis</th><th>Yang harus dibuktikan</th></tr></thead><tbody><tr><td>Indonesia</td><td>Bahasa dan konteks lokal jika ini kemampuan terkuat Anda.</td><td>Permintaan topik, retensi, dan biaya produksi.</td></tr><tr><td>Penonton berbahasa Inggris</td><td>Potensi menjangkau lintas negara.</td><td>Kejelasan bahasa, persaingan, lokasi penonton aktual, dan RPM sendiri.</td></tr><tr><td>Segmen profesional tertentu</td><td>Masalah penonton dapat didefinisikan lebih spesifik.</td><td>Keahlian Anda dan apakah konten memberi manfaat nyata.</td></tr></tbody></table></div><p class="sub section-space">Pilih satu bahasa dan satu kelompok penonton untuk uji awal. Data negara penonton harus dicatat dari YouTube Studio, bukan diperkirakan dari bahasa judul.</p></div>`;}
function sources(){const list=state('sources',[]);return `${heading('Sumber & izin','Catat hak penggunaan dan kontribusi Anda untuk setiap sumber.',btn('+ Catat sumber','new-source'))}<div class="grid two"><div class="card"><span class="badge lime">Pilihan utama</span><h2 class="section-space">Rekaman sendiri</h2><p class="sub">Tutorial layar, demonstrasi, atau wawancara dengan izin peserta. Periksa pula musik dan aset yang ikut terekam.</p></div><div class="card"><span class="badge amber">Periksa per video</span><h2 class="section-space">Kreator pihak lain</h2><p class="sub">Tidak ada nama YouTuber yang otomatis aman. Catat bukti izin komersial, batas penggunaan, dan hak atas musik atau tamu. Status di sini adalah catatan Anda, bukan verifikasi hukum otomatis.</p></div></div><div class="card section-space"><h2>Daftar sumber Anda</h2>${list.length?`<div class="table-wrap"><table><thead><tr><th>Sumber</th><th>Status catatan</th><th>Kontribusi orisinal</th><th>Aksi</th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${esc(s.creator)}</strong><br>${safeLink(s.url,'Buka sumber')}<br><small>${esc(s.scope)}</small></td><td><span class="badge ${s.rights==='own'?'lime':'amber'}">${rightsLabel(s.rights)}</span><br><small>${s.evidence?esc(s.evidence):'Belum ada bukti dicatat'}</small></td><td>${esc(s.contribution||'Belum diisi')}</td><td><button class="small" data-edit-source="${s.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('Sumber belum dicatat','Mulai dari rekaman sendiri atau sumber yang izin komersialnya dapat Anda buktikan.',btn('Catat sumber pertama','new-source','small'))}</div><div class="note section-space">Izin penggunaan dan kelayakan monetisasi dinilai terpisah. Pencantuman kredit tidak menggantikan izin. <a href="https://support.google.com/youtube/answer/1311392" target="_blank" rel="noopener">Baca kebijakan YouTube</a>.</div>`;}
function rightsLabel(x){return {own:'Rekaman sendiri',permission:'Izin dicatat pengguna',cc:'Lisensi dicatat pengguna',pending:'Belum ada izin'}[x]||'Belum diperiksa';}
function safeLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '';return `<a class="source-link" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${label}</a>`}catch{return ''}}
function calendar(){const list=state('calendar',[]).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `${heading('Kalender konten','Jadwal produksi dan publikasi yang bisa Anda jalankan.',btn('+ Jadwalkan konten','new-calendar'))}<div class="grid split"><div class="card"><div class="card-header"><h2>Agenda publikasi</h2><span class="badge">${list.length} konten</span></div>${list.length?list.map(c=>`<article class="calendar-day"><div class="row between"><time>${esc(c.date)} · ${esc(c.time)} ${esc(c.zone)}</time><span class="badge ${c.status==='published'?'lime':''}">${{idea:'Ide',ready:'Siap unggah',published:'Sudah terbit'}[c.status]||'Ide'}</span></div><h3>${esc(c.title)}</h3><p class="sub">${esc(c.description)}</p><div class="row"><button class="small" data-edit-calendar="${c.id}">Edit agenda</button>${c.status!=='published'?`<button class="small ghost" data-publish="${c.id}">Tandai sudah terbit</button>`:''}</div></article>`).join(''):empty('Kalender masih kosong','Jadwalkan konten pertama setelah ide dan sumbernya jelas.',btn('Tambah agenda','new-calendar','small'))}</div><aside><div class="card"><span class="badge amber">Rencana uji</span><h2 class="section-space">${esc(data.mentor.cadence)}</h2><p class="sub">Mulai dengan 19.00 waktu pasar target dan bandingkan dengan 12.00. Keduanya hipotesis, bukan jam terbaik yang telah terbukti untuk channel Anda.</p><p class="sub">Uji satu variabel pada konten yang sebanding, lalu catat hasil setelah 48 jam dan 7 hari.</p><div class="note">Kalender ini menyimpan rencana. Publikasi dilakukan melalui YouTube Studio; tidak ada unggahan otomatis atau pengingat latar belakang.</div><a class="chip section-space" style="display:inline-block" href="https://studio.youtube.com" target="_blank" rel="noopener">Buka YouTube Studio</a></div></aside></div>`;}
function analytics(){const rows=state('metrics',[]),total=rows.reduce((s,r)=>s+Number(r.views),0),rev=rows.reduce((s,r)=>s+Number(r.revenue||0),0),cost=rows.reduce((s,r)=>s+Number(r.cost||0),0);const short=rows.filter(r=>r.format==='short'),long=rows.filter(r=>r.format==='long');function summary(list){if(!list.length)return 'Belum ada data';const views=list.reduce((s,r)=>s+Number(r.views),0);return `${list.length} video · ${fmt(views)} tayangan`;}return `${heading('Evaluasi channel','Catat hasil nyata, lalu putuskan apa yang layak dilanjutkan.',btn('+ Catat hasil video','new-metric'))}<div class="grid four"><div class="card stat"><span>Tayangan tercatat</span><strong>${fmt(total)}</strong><p class="sub">${rows.length} catatan video</p></div><div class="card stat"><span>Pendapatan</span><strong style="font-size:1.45rem">${money(rev)}</strong><p class="sub">Berdasarkan input Anda</p></div><div class="card stat"><span>Biaya tercatat</span><strong style="font-size:1.45rem">${money(cost)}</strong><p class="sub">Produksi & operasional</p></div><div class="card stat"><span>Selisih pendapatan − biaya</span><strong style="font-size:1.45rem">${money(rev-cost)}</strong><p class="sub">Belum termasuk pajak/biaya tak tercatat</p></div></div><div class="grid two section-space"><div class="card"><h2>Shorts</h2><p class="sub">${summary(short)}</p><p class="sub">Bandingkan viewed vs swiped away, retensi, dan subscriber per 1.000 tayangan. Jangan campur RPM Shorts dengan video panjang.</p></div><div class="card"><h2>Video panjang</h2><p class="sub">${summary(long)}</p><p class="sub">Bandingkan CTR impresi, durasi tonton, dan retensi. CTR tidak menggantikan pemeriksaan kepuasan penonton.</p></div></div><div class="card section-space"><h2>Catatan performa</h2>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Konten</th><th>Umur data</th><th>Tayangan</th><th>Retensi</th><th>Subscriber baru</th><th>Pendapatan</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td><strong>${esc(m.title)}</strong><br><small>${m.format==='short'?'Shorts':'Video panjang'} · ${esc(m.date)} · ${esc(m.time||'')}<br>${esc(m.market||'Pasar belum dicatat')}</small></td><td>${esc(m.age)} jam</td><td>${fmt(m.views)}</td><td>${fmt(m.retention)}%</td><td>${fmt(m.subs)}</td><td>${money(m.revenue)}</td><td><button class="small" data-edit-metric="${m.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data performa','Masukkan metrik dari YouTube Studio. Tidak ada angka contoh yang dihitung sebagai hasil Anda.')}</div><div class="card section-space"><h2>Kesimpulan eksperimen</h2>${experimentSummary(rows)}</div>`;}
function median(arr){if(!arr.length)return 0;const s=arr.slice().sort((a,b)=>a-b),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2;}
function experimentSummary(rows){const same=rows.filter(r=>r.format==='short'&&Number(r.age)===48);const groups={};same.forEach(r=>{let k=r.time||'Tidak dicatat';(groups[k]??=[]).push(Number(r.views))});if(Object.values(groups).filter(g=>g.length>=5).length<2)return '<div class="note">Belum cukup catatan yang sebanding. Untuk uji jam, catat minimal 5 Shorts per kelompok pada umur 48 jam, dengan niche dan kualitas yang serupa. Ini ambang kerja praktis, bukan bukti statistik atau aturan YouTube.</div>';return `<p class="sub">Ringkasan deskriptif Shorts pada umur 48 jam. Perbedaan topik, kualitas, dan audiens tetap bisa menjelaskan hasil; ini bukan bukti sebab akibat.</p><div class="row">${Object.entries(groups).map(([k,v])=>`<div class="chip">${esc(k)} · ${v.length} video · median ${fmt(median(v))} tayangan</div>`).join('')}</div>`;}
const CHECKS=[['twofa','Verifikasi dua langkah aktif'],['strikes','Tidak ada teguran Pedoman Komunitas aktif'],['advanced','Akses fitur lanjutan tersedia'],['country','Negara channel mendukung jalur YPP yang dipilih'],['adsense','AdSense siap ditautkan melalui YouTube Studio'],['rights','Hak sumber, musik, dan aset telah diperiksa'],['original','Kontribusi orisinal terlihat pada video utama channel'],['review','Judul, thumbnail, dan deskripsi sesuai isi']];
function monetization(){const m=state('monetization',{}),s=Number(m.subscribers||0),h=Number(m.hours||0),v=Number(m.shorts||0),u=Number(m.uploads||0),check=state('checklist',{});const early=s>=500&&u>=3&&(h>=3000||v>=3000000),ads=s>=1000&&(h>=4000||v>=10000000);function progress(label,n,target){return `<div class="row between"><span class="sub">${label}</span><span class="sub number">${fmt(n)} / ${fmt(target)}</span></div><div class="progress"><i style="width:${Math.min(n/target*100,100)}%"></i></div>`;}return `${heading('Menuju monetisasi','Pantau ambang pengajuan dan kesiapan channel secara terpisah.')}<div class="grid two"><div class="card"><span class="badge ${early?'lime':''}">${early?'Ambang angka tercapai':'Akses awal YPP'}</span><h2 class="section-space">Pendanaan penggemar & fitur tertentu</h2>${progress('Subscriber',s,500)}${progress('Unggahan publik / 90 hari',u,3)}${progress('Jam tonton valid / 12 bulan',h,3000)}<p class="sub">ATAU</p>${progress('Shorts valid / 90 hari',v,3000000)}<p class="sub section-space">Tersedia di negara yang memenuhi syarat. Bukan otomatis bagi hasil iklan.</p></div><div class="card"><span class="badge ${ads?'lime':''}">${ads?'Ambang angka tercapai':'Jalur iklan'}</span><h2 class="section-space">Bagi hasil iklan & YouTube Premium</h2>${progress('Subscriber',s,1000)}${progress('Jam tonton valid / 12 bulan',h,4000)}<p class="sub">ATAU</p>${progress('Shorts valid / 90 hari',v,10000000)}<div class="note section-space">Angka terpenuhi berarti dapat memeriksa kelayakan pengajuan. Keputusan akhir mengikuti peninjauan YouTube, bukan aplikasi ini.</div></div></div><div class="grid two section-space"><div class="card"><h2>Perbarui angka channel</h2><p class="sub">Salin dari tab Penghasilan YouTube Studio. Jam dari Shorts Feed tidak masuk jalur jam tonton.</p><form id="monetization-form"><div class="formgrid">${field('Subscriber','subscribers',s,'number','min="0" required')}${field('Unggahan publik valid / 90 hari','uploads',u,'number','min="0" required')}${field('Jam tonton publik valid / 12 bulan','hours',h,'number','min="0" step="0.1" required')}${field('Penayangan Shorts valid / 90 hari','shorts',v,'number','min="0" required')}</div><button class="primary" type="submit">Simpan perkembangan</button></form></div><div class="card"><h2>Kesiapan pengajuan</h2>${CHECKS.map(([k,l])=>`<label class="checkrow"><input type="checkbox" data-check="${k}" ${check[k]?'checked':''}>${l}</label>`).join('')}<p class="sub">Daftar periksa mandiri, bukan sertifikasi kelayakan. <a href="https://studio.youtube.com" target="_blank" rel="noopener">Periksa tab Penghasilan</a>.</p></div></div><div class="card section-space"><h2>Simulasi pendapatan dan biaya</h2><p class="sub">Masukkan asumsi RPM dari data Anda. Nilai awal nol; tidak ada tarif negara atau janji penghasilan. Untuk Shorts, gunakan basis penayangan yang sesuai dengan RPM di Analytics.</p><div class="formgrid" id="calculator">${field('Tayangan / engaged views sesuai basis RPM','calcviews',0,'number','min="0"')}${field('Asumsi RPM (Rp per 1.000)','calcrpm',0,'number','min="0"')}${field('Biaya bulanan (Rp)','calccost',state('profile',{}).budget||0,'number','min="0"')}</div><div class="row"><span class="badge">Simulasi</span><strong id="calc-result">${money(-(state('profile',{}).budget||0))} setelah biaya</strong></div><p class="sub section-space">Tanpa pendapatan: kerugian sebesar biaya. Hasil simulasi belum memperhitungkan pajak dan tidak berlaku sebagai prediksi.</p></div>`;}
function researchView(){return `${heading('Dasar riset','Sumber resmi, rekomendasi praktis, dan batas pengetahuan dipisahkan.')}<div class="row"><span class="badge lime">Fakta bersumber</span><span class="badge amber">Hipotesis untuk diuji</span><span class="badge">Data channel Anda</span></div><p class="sub section-space">Sumber ditinjau ${esc(research.reviewed)}. Ini arsip riset awal, bukan pembaruan web otomatis. Buka sumber sebelum mengambil keputusan penting atau mengajukan monetisasi.</p><div class="research">${research.sources.map(s=>`<article class="card"><div class="row between"><h3>${esc(s.title)}</h3><span class="badge lime">Sumber resmi</span></div><p>${esc(s.fact)}</p><p class="muted"><strong>Penerapan:</strong> ${esc(s.action)}</p>${safeLink(s.url,'Baca sumber YouTube')}</article>`).join('')}</div><div class="note section-space">Rekomendasi niche, pola judul, frekuensi produksi, dan slot jam awal adalah rancangan eksperimen aplikasi. Semuanya tidak diklaim sebagai hasil riset kausal, peringkat pasar terbaru, atau jaminan lolos monetisasi.</div>`;}
function settings(){return `${heading('Pengaturan','Kelola akses dan salinan data ruang kerja Anda.')}<div class="grid two"><div class="card"><h2>Status kemampuan</h2><table><tbody><tr><td>Potong, crop & ekspor video</td><td><span class="badge ${data.capabilities.ffmpeg?'lime':'red'}">${data.capabilities.ffmpeg?'Tersedia':'Belum tersedia'}</span></td></tr><tr><td>Transkripsi lokal</td><td><span class="badge ${data.capabilities.transcription?'lime':'amber'}">${data.capabilities.transcription?'Terpasang':'Belum terpasang'}</span></td></tr><tr><td>Model transkripsi</td><td>${esc(data.capabilities.model)}</td></tr><tr><td>Mentor</td><td>${data.capabilities.ai?'Coach AI aktif · Gemma / Groq':'Coach AI belum disiapkan'}</td></tr><tr><td>Sinkron YouTube</td><td>Input manual</td></tr><tr><td>Pelacakan wajah otomatis</td><td>Belum tersedia; crop dapat diatur</td></tr></tbody></table><p class="sub section-space">Aplikasi ini tidak menyimpan kata sandi Google dan tidak mengunggah video otomatis. Coach memakai profil, metrik, dan snapshot sumber. Belum ada riset web langsung. Kunci AI hanya disimpan di server. Caption YouTube diambil langsung bila tersedia.</p></div><div class="card"><h2>Ganti kata sandi</h2><form id="password-form">${field('Kata sandi saat ini','current','','password','required autocomplete="current-password"')}${field('Kata sandi baru','password','','password','required minlength="12" autocomplete="new-password"')}<button class="primary" type="submit">Simpan kata sandi baru</button></form></div><div class="card"><h2>Cadangkan data</h2><p class="sub">Unduh profil, tugas, izin, kalender, dan metrik sebagai JSON. Video dan berkas ekspor diunduh terpisah dari Studio.</p>${btn('Unduh cadangan JSON','backup','ghost')}</div><div class="card"><h2>Akses pribadi</h2><p class="sub">Sesi masuk berlaku tujuh hari. Hanya pemilik kata sandi yang dapat melihat media dan catatan.</p>${btn('Keluar dari akun','logout','ghost')}</div></div>`;}
function studio(){
 const r=data.media.find(m=>m.id===selected),trans=state('transcript:'+selected,{segments:[],candidates:[]}),yt=state('youtube:'+selected,null),virtual=r?.ext==='.youtube';
 return `${heading('Studio klip','Dari tautan atau berkas video → transkrip → poin bernilai → klip.')}<div class="grid split"><div class="card"><div class="card-header"><h2>${r?esc(r.name):'Mulai dari sumber video'}</h2><span class="badge lime">Caption langsung · AI highlights</span></div>${r?`
 <div class="video-stage">${virtual?`<iframe id="yt-preview" title="Pratinjau YouTube" src="https://www.youtube-nocookie.com/embed/${esc(yt?.video_id||'')}" allow="fullscreen" allowfullscreen></iframe>`:`<video id="preview" src="/media/media/${r.id}${r.ext}" controls playsinline preload="metadata"></video>`}</div>
 ${yt?`<p class="sub">${safeLink(yt.url,'Buka video di YouTube')} · ${trans.source==='youtube'?'Caption YouTube '+(trans.is_generated?'otomatis':'manual')+' · '+esc(trans.language):'Transkrip yang diimpor'}</p>`:''}
 <div class="tabs">${[['edit','Potong & ekspor'],['subtitles',`Subtitle (${trans.segments.length})`],['candidates','Poin bernilai AI']].map(([k,t])=>`<button data-studio-tab="${k}" class="${subtab===k?'active':''}">${t}</button>`).join('')}</div>
 ${subtab==='edit'?`<form id="render-form"><div class="formgrid">${field('Mulai (detik)','start',0,'number','min="0" step="0.001" required')}${field('Selesai (detik)','end',Math.min(45,r.duration).toFixed(3),'number',`min="1" max="${r.duration}" step="0.001" required`)}${field('Nama hasil','name',r.name.replace(/\.[^.]+$/,''),'text','required maxlength="140"')}${select('Format','format',[['vertical','Vertikal · 9:16'],['square','Persegi · 1:1'],['landscape','Lanskap · 16:9']],'vertical')}</div>
 ${virtual?`<div class="note">Caption dan analisis siap tanpa mengunduh audio. Untuk ekspor MP4, ambil berkas video yang Anda berhak gunakan atau hubungkan unggahan asli di bawah.</div>`:`<label class="field">Posisi crop: <span id="position-label">50%</span><input type="range" name="position" min="0" max="100" value="50"></label>${select('Narasi orisinal (opsional)','narration',[['','Gunakan audio sumber'],...data.media.filter(m=>m.audio&&!m.width).map(m=>[m.id,m.name])],'')}<label class="checkrow"><input name="subtitles" type="checkbox" ${trans.segments.length?'checked':''}>Tempel subtitle</label>`}
 <div class="row section-space"><button class="primary" type="submit" ${virtual?'disabled':''}>Ekspor MP4</button>${btn('Pratinjau rentang','preview-range','ghost','type="button"')}${btn('Unduh SRT rentang','range-srt','ghost','type="button"')}</div></form>
 ${virtual?`<div class="section-space"><label class="checkrow"><input id="youtube-rights" type="checkbox">Saya memiliki hak untuk mengunduh dan mengolah video ini.</label>${btn('Ambil berkas video untuk ekspor','youtube-video','ghost')}<p class="sub">Pengambilan video dapat ditolak YouTube; tidak memengaruhi transkrip yang tersimpan.</p><form id="attach-form">${select('Atau gunakan video penuh yang sudah diunggah','target',[['','Pilih berkas video'],...data.media.filter(m=>m.width&&m.ext!=='.youtube'&&m.id!==selected).map(m=>[m.id,m.name])],'')}<p class="sub">Gunakan video yang sama, tanpa perubahan waktu/potongan. Periksa sinkronisasi subtitle sebelum ekspor.</p><button type="submit" class="small">Hubungkan transkrip ke berkas</button></form></div>`:''}`:
 subtab==='subtitles'?`<div class="row">${yt?btn('Ambil ulang caption YouTube','youtube-refresh'):btn('Transkripsi audio lokal','transcribe')}${btn('Impor SRT','import-srt','ghost')}${btn('Simpan koreksi','save-subtitles','ghost')}${btn('Unduh SRT lengkap','full-srt','ghost')}</div><p class="sub section-space">${trans.source==='youtube'?'Teks dan timestamp diambil dari caption yang tersedia di YouTube. Tidak menggunakan MP3 atau pengenalan suara lokal.':'Periksa ejaan, konteks, dan waktu subtitle.'}</p><div class="subtitle-editor">${trans.segments.length?trans.segments.map((s,i)=>`<div class="subtitle-row"><time>${stamp(s.start)}<br>${stamp(s.end)}</time><textarea aria-label="Subtitle ${i+1}" data-subtitle="${i}">${esc(s.text)}</textarea></div>`).join(''):empty('Belum ada subtitle','Ambil caption YouTube atau impor SRT.')}</div>`:
 `<div class="note">AI membaca teks dan timestamp untuk mencari pelajaran, cerita, atau penjelasan yang utuh. Rekomendasi bukan prediksi viral. Periksa konteks, visual, dan hak penggunaan.</div><div class="row section-space">${btn('Analisis poin bernilai dengan AI','analyze')}<span class="sub">${trans.analysis?trans.analysis.segments_reviewed+' segmen diperiksa · '+trans.analysis.chunks+' bagian':'Seluruh transkrip akan diperiksa'}</span></div>${(trans.candidates||[]).map((c,i)=>`<article class="calendar-day section-space"><div class="row between"><time>${stamp(c.start)} — ${stamp(c.end)}</time><span class="badge">${c.method==='ai'?'Analisis AI':'Kandidat aturan awal'}</span></div><h3>${esc(c.title||'Kandidat '+(i+1))}</h3><p>${esc(c.reason)}</p><p class="sub">${esc(c.text)}</p>${c.contribution?`<p class="note"><strong>Tambahkan nilai:</strong> ${esc(c.contribution)}</p>`:''}${c.caution?`<p class="sub">Periksa: ${esc(c.caution)}</p>`:''}<button class="small" data-candidate="${i}">Gunakan ${stamp(c.start)} – ${stamp(c.end)}</button></article>`).join('')||empty('Temukan bagian paling berguna','Ambil transkrip, lalu jalankan analisis AI.')}`}`:empty('Tempel tautan. Temukan ceritanya.','Gunakan panel YouTube atau unggah video Anda untuk mulai.')}</div>
 <div><section class="card"><span class="badge lime">BARU · YOUTUBE</span><h2 class="section-space">Mulai dari tautan</h2><form id="youtube-form">${field('Tautan video YouTube','url','','url','required placeholder="https://www.youtube.com/watch?v=…"')}${select('Bahasa caption yang diutamakan','language',[['id','Indonesia'],['en','Inggris']],state('profile',{}).language||'id')}<button class="primary" type="submit">Ambil transkrip YouTube</button><p class="sub section-space">Caption manual / otomatis yang tersedia beserta timestamp. Jika bahasa pilihan tidak tersedia, gunakan bahasa caption yang tersedia. Tidak mengunduh MP3.</p></form></section>
 <section class="card section-space"><h2>Media proyek</h2><div class="upload">${icon('upload')}<h3>Unggah video atau narasi</h3><p>Maksimal 500 MB · 120 menit</p><input type="file" id="upload" accept="video/*,audio/*" aria-label="Unggah media"><div id="upload-status" class="sub section-space"></div></div><div class="media-list">${data.media.map(m=>`<div class="media-item ${selected===m.id?'selected':''}"><div class="grow"><div class="name">${esc(m.name)}</div><small>${m.ext==='.youtube'?'Tautan YouTube':m.width?'Video':'Audio'} · ${stamp(m.duration)}</small></div>${m.width?`<button class="small" data-open-media="${m.id}">Pilih</button>`:''}<button class="small ghost danger" data-delete-media="${m.id}" aria-label="Hapus media">×</button></div>`).join('')}</div></section><section class="card section-space"><h2>Antrean proses</h2><div id="job-list">${joblist()}</div></section><section class="card section-space"><h2>Hak penggunaan</h2><p class="sub">Caption yang tersedia tidak berarti izin untuk mengunggah ulang. Catat hak sumber dan kontribusi Anda.</p><button class="ghost small" data-nav="sources">Sumber & izin</button></section></div></div><section class="card section-space"><h2>Hasil ekspor</h2>${exportsView()}</section>`;
}
const QUESTS=[
 {title:'Fondasi',desc:'Kenali penonton dan arah channel.',ids:['profile','channel','source','idea']},
 {title:'Kreator',desc:'Buat konten dengan nilai orisinal.',ids:['original','clip']},
 {title:'Publikasi',desc:'Terbitkan dan catat hasil awal.',ids:['publish','review']},
 {title:'Eksperimen',desc:'Pelajari pola dari beberapa konten.',ids:['experiment','comparison']},
 {title:'Bisnis channel',desc:'Tinjau kebijakan dan pendapatan aktual.',ids:['audit','income']}
];
const EXTRA_TASKS=[['experiment','Selesaikan satu eksperimen','Bandingkan konten sejenis dan ubah satu hal saja. Catat minimal 5 konten per variasi jika kapasitas memungkinkan.','analytics'],['comparison','Tulis keputusan dari hasil','Catat apa yang dilanjutkan, dihentikan, dan diuji lagi, beserta batas data.','analytics'],['audit','Audit kesiapan monetisasi','Periksa orisinalitas, hak sumber, persyaratan terkini, dan kesiapan pengajuan.','monetization'],['income','Catat hasil bisnis nyata','Catat pendapatan aktual (termasuk nol), biaya dan laba bersih; tentukan langkah berikutnya.','monetization']];
function journey(){const done=state('tasks',{}),missions=state('coachMissions',[]),checked=state('coachTasks',{}),total=QUESTS.flatMap(q=>q.ids).filter(id=>done[id]).length,bonus=missions.filter(m=>checked[m.id]).length;let level=QUESTS.findIndex(q=>!q.ids.every(id=>done[id]));if(level<0)level=QUESTS.length-1;return `<section class="card quest-hero"><div class="row between"><div><div class="eyebrow">PERJALANAN KREATOR ANDA</div><h2>Level ${level+1} · ${QUESTS[level].title}</h2><p class="sub">${QUESTS[level].desc}</p></div><div class="xp"><strong>${total*100+bonus*25}</strong><span>XP aktivitas</span></div></div><div class="quest-map">${QUESTS.map((q,i)=>`<div class="quest-node ${i===level?'current':''} ${q.ids.every(id=>done[id])?'complete':''}"><span>${q.ids.every(id=>done[id])?'✓':i+1}</span><strong>${q.title}</strong><small>${q.ids.filter(id=>done[id]).length}/${q.ids.length} misi</small></div>`).join('')}</div><div class="progress"><i style="width:${total/12*100}%"></i></div><p class="sub">${total}/12 misi utama · XP dihitung dari tugas yang Anda tandai selesai, bukan bukti kelayakan monetisasi.</p></section>`;}
function mentor(){const history=state('coachHistory',[]),missions=state('coachMissions',[]),done=state('coachTasks',{}),n=state('coachNiches',[]),pending=data.jobs.some(j=>j.kind==='coach'&&['running','queued'].includes(j.status));return `${heading('Coach pribadi Anda','Tahu posisi Anda hari ini. Punya langkah jelas untuk besok.','<span class="badge lime">Vira · AI coach</span>')}${journey()}<div class="grid split section-space"><section class="card"><div class="card-header"><h2>Ngobrol dengan Vira</h2><span class="badge">${data.capabilities.ai?'AI terhubung':'AI belum dikonfigurasi'}</span></div><p class="sub">Coach membaca profil, misi, dan metrik yang Anda simpan. Profil serta pesan dikirim ke OpenRouter/Groq untuk menjawab. Statistik channel masih Anda isi; coach tidak mengakses YouTube Studio.</p><div class="coach-chat" id="coach-chat" role="log" aria-live="polite">${history.length?history.map(h=>`<article class="chat-message ${h.role==='user'?'user':'assistant'}"><strong>${h.role==='user'?'Anda':'Vira'}</strong><div>${esc(h.text)}</div>${h.meta?`<small>${esc(h.meta.provider)} · ${esc(h.meta.model)}${h.meta.fallback?' · layanan cadangan':''}</small>`:''}</article>`).join(''):'<div class="coach-welcome"><span>✦</span><h3>Kita mulai dari keunggulan Anda.</h3><p>Ceritakan kemampuan, waktu luang, dan tujuan channel. Saya bantu membandingkan niche lalu menyusun misi pertama.</p></div>'}</div><div class="coach-shortcuts">${[['niche','Bantu pilih niche'],['today','Misi hari ini'],['review','Evaluasi hasil'],['stuck','Saya sedang buntu']].map(([k,v])=>`<button class="small ghost" data-coach-prompt="${k}" ${pending?'disabled':''}>${v}</button>`).join('')}</div><form id="coach-form">${area('Pesan untuk coach','message','','required minlength="2" maxlength="4000" placeholder="Saya punya waktu 1 jam sehari. Niche apa yang cocok dengan kemampuan saya?"')}<button class="primary" type="submit" ${pending?'disabled':''}>${pending?'Coach sedang menyusun jawaban…':'Kirim ke Vira'}</button></form><div id="job-list" class="section-space">${joblist()}</div></section><div><section class="card"><h2>Misi pribadi dari coach</h2><p class="sub">Tandai setelah benar-benar dikerjakan. Misi memberi 25 XP dan menjadi konteks sesi berikutnya.</p>${missions.length?missions.slice().reverse().map(m=>`<label class="task ${done[m.id]?'done':''}"><input type="checkbox" data-coach-task="${esc(m.id)}" ${done[m.id]?'checked':''}><div><strong>${esc(m.title)}</strong><p>${esc(m.detail)}</p><small>${esc(m.minutes)} menit · +25 XP</small></div></label>`).join(''):empty('Misi pertama menunggu','Isi profil di bawah, kemudian minta rencana dari Vira.')}</section>${n.length?`<section class="card section-space"><h2>Pilihan niche untuk Anda</h2><p class="sub">Saran AI untuk diuji. Anda yang memilih arah akhirnya.</p>${n.map((x,i)=>`<article class="calendar-day"><h3>${esc(x.name)}</h3><p class="sub">${esc(x.fit)}</p><p>${esc(x.experiment)}</p><button class="small" data-coach-niche="${i}">Pilih niche ini</button></article>`).join('')}</section>`:''}</div></div><section class="card section-space"><h2>Misi lanjutan</h2>${EXTRA_TASKS.map(([id,title,desc,nav])=>`<label class="task ${state('tasks',{})[id]?'done':''}"><input type="checkbox" data-task="${id}" ${state('tasks',{})[id]?'checked':''}><div><strong>${title}</strong><p>${desc} <a href="#${nav}">Buka</a></p></div></label>`).join('')}</section><div class="section-space">${mentorLegacy()}</div>`;}
function subtitleFile(rows,start=0,end=Infinity){const ts=t=>{const ms=Math.max(0,Math.round(t*1000)),h=Math.floor(ms/3600000),m=Math.floor(ms/60000)%60,s=Math.floor(ms/1000)%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')},${String(ms%1000).padStart(3,'0')}`};return rows.filter(s=>s.end>start&&s.start<end).map((s,i)=>`${i+1}\n${ts(Math.max(0,s.start-start))} --> ${ts(Math.min(end,s.end)-start)}\n${s.text}\n`).join('\n');}
async function sendCoach(message){const r=await api('coach',{message});await refresh();render();watchJob(r.job);toast('Vira sedang membaca konteks Anda.');}

const views={dashboard,studio,mentor,niches,sources,calendar,analytics,monetization,research:researchView,settings};
function sourceForm(id){const s=state('sources',[]).find(s=>s.id===id)||{};modal(s.id?'Edit sumber':'Catat sumber',`<form id="source-form" data-id="${s.id||''}">${field('Kreator / pemilik rekaman','creator',s.creator||'','text','required maxlength="140"')}${field('Tautan video atau sumber','url',s.url||'','url','placeholder="https://…"')}${select('Dasar penggunaan','rights',[['own','Rekaman sendiri'],['permission','Izin tertulis pemilik'],['cc','Lisensi penggunaan ulang'],['pending','Belum mendapat izin']],s.rights||'pending')}${area('Bukti izin / lokasi dokumen','evidence',s.evidence||'','placeholder="Tautan pernyataan resmi atau lokasi surat izin; tanggal pemeriksaan"')}${area('Cakupan dan batas izin','scope',s.scope||'','placeholder="Apakah boleh komersial? Perlu atribusi? Apakah musik dan tamu tercakup?"')}${area('Kontribusi orisinal yang akan Anda tambahkan','contribution',s.contribution||'','required placeholder="Analisis, narasi, demonstrasi, atau contoh Anda"')}<div class="note">Izin dicatat berdasarkan informasi Anda. Aplikasi tidak mengonfirmasi izin kreator secara otomatis.</div><div class="row section-space"><button class="primary" type="submit">Simpan sumber</button>${s.id?`<button type="button" class="danger ghost" data-delete-source="${s.id}">Hapus catatan</button>`:''}</div></form>`);}
function calendarForm(id){const c=state('calendar',[]).find(c=>c.id===id)||{};modal(c.id?'Edit agenda':'Jadwalkan konten',`<form id="calendar-form" data-id="${c.id||''}">${field('Judul konten','title',c.title||'','text','required maxlength="180"')}<div class="formgrid">${field('Tanggal publikasi','date',c.date||new Date().toLocaleDateString('en-CA'),'date','required')}${field('Jam','time',c.time||'19:00','time','required')}${select('Zona waktu pasar','zone',[['WIB','WIB'],['WITA','WITA'],['WIT','WIT'],['America/New_York','New York (perhatikan DST)'],['Europe/London','London (perhatikan DST)']],c.zone||'WIB')}${select('Status','status',[['idea','Ide'],['ready','Siap unggah'],['published','Sudah terbit']],c.status||'idea')}</div>${area('Caption / deskripsi / catatan produksi','description',c.description||'')}<div class="row"><button class="primary" type="submit">Simpan agenda</button>${c.id?`<button type="button" class="danger ghost" data-delete-calendar="${c.id}">Hapus</button>`:''}</div></form>`);}
function metricForm(id){const m=state('metrics',[]).find(x=>x.id===id)||{};modal(m.id?'Edit hasil konten':'Catat hasil konten',`<form id="metric-form" data-id="${m.id||''}">${field('Judul video','title',m.title||'','text','required maxlength="180"')}<div class="formgrid">${select('Format','format',[['short','Shorts'],['long','Video panjang']],m.format||'short')}${field('Tanggal terbit','date',m.date||new Date().toLocaleDateString('en-CA'),'date','required')}${field('Jam terbit (zona waktu konsisten)','time',m.time||'19:00','time','required')}${field('Umur video saat dicatat (jam)','age',m.age||48,'number','min="1" required')}${field('Tayangan','views',m.views||0,'number','min="0" required')}${field('Rata-rata persentase ditonton (%)','retention',m.retention||0,'number','min="0" max="1000" step="0.1" required')}${field('Subscriber diperoleh','subs',m.subs||0,'number','min="0" required')}${field('Negara / pasar aktual','market',m.market||'','text','placeholder="Dari Analytics"')}${field('Pendapatan video (Rp)','revenue',m.revenue||0,'number','min="0" step="0.01" required')}${field('Biaya yang dialokasikan (Rp)','cost',m.cost||0,'number','min="0" required')}</div><p class="sub">Satu catatan per video dan umur pengukuran. Edit catatan lama untuk memperbarui hasil, agar pendapatan tidak dihitung ganda.</p><div class="row"><button class="primary" type="submit">Simpan hasil</button>${m.id?`<button type="button" class="danger ghost" data-delete-metric="${m.id}">Hapus</button>`:''}</div></form>`);}
function login(){route='dashboard';$('#app').innerHTML=`<main class="login"><div class="brand"><img src="/favicon.svg" alt="">ViraClip</div><div class="eyebrow">Studio & mentor kreator</div><h1>Ruang untuk bertumbuh.</h1><p>Masuk untuk membuat klip, menyusun langkah berikutnya, dan belajar dari hasil channel Anda.</p><form id="login-form">${field('Kata sandi workspace','password','','password','required autocomplete="current-password"')}<button class="primary" type="submit">Masuk ke workspace</button><div id="login-error" class="error" role="alert"></div></form><p class="footer-note">Ruang pribadi · Video dan catatan dilindungi sesi masuk.</p></main>`;}
async function upload(file){if(!file)return;if(file.size>500*1024*1024)return toast('Ukuran maksimal 500 MB.');const status=$('#upload-status');status.textContent='Mengunggah 0%';$('#upload').disabled=true;await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/upload');xhr.setRequestHeader('X-ViraClip','1');xhr.setRequestHeader('X-Filename',encodeURIComponent(file.name));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable&&$('#upload-status'))$('#upload-status').textContent=`Mengunggah ${Math.round(e.loaded/e.total*100)}%`;};xhr.onload=()=>{let r;try{r=JSON.parse(xhr.responseText)}catch{return reject(Error('Server tidak merespons. Coba berkas lebih kecil.'))}if(xhr.status>=400)return reject(Error(r.error));if(r.width)selected=r.id;resolve();};xhr.onerror=()=>reject(Error('Koneksi unggahan terputus.'));xhr.send(file);});await refresh();render();toast('Media berhasil disimpan.');}
async function watchJob(id){const poll=async()=>{try{const j=await api('jobs/'+id);const i=data.jobs.findIndex(x=>x.id===id);if(i>=0)data.jobs[i]=j;else data.jobs.unshift(j);if($('#job-list'))$('#job-list').innerHTML=joblist();if(['done','error'].includes(j.status)){await refresh();if(j.status==='done'&&j.result?.media&&route==='studio')selected=j.result.media;if(['studio','mentor'].includes(route))render();toast(j.message);return;}setTimeout(poll,2500);}catch(e){toast(e.message);}};poll();}
async function saveList(key,form,extra={}){const body=Object.fromEntries(new FormData(form));const id=form.dataset.id||uid();const list=state(key,[]).slice();const idx=list.findIndex(x=>x.id===id);const row={...body,...extra,id};if(idx>=0)list[idx]=row;else list.push(row);await save(key,list);$('#modal').close();render();toast('Tersimpan.');}
function copyPack(b){const niche=research.niches.find(n=>n.id===state('profile',{}).niche)||research.niches[0];const topic=b.topic.trim(),take=b.takeaway.trim(),evidence=b.evidence.trim();const titles=[`${topic}: langkah yang bisa langsung dicoba`,`${topic} — contoh nyata dan hasilnya`,`${topic}: apa yang perlu diperhatikan?`];const desc=`${take}\n\n${evidence?'Sumber / bukti: '+evidence+'\n':''}Penjelasan dan contoh disusun oleh ${state('profile',{}).channel||'kreator channel ini'}.${b.hashtags?'\n\n'+niche.hashtags.join(' '):''}`;return {topic,titles,description:desc,script:`PEMBUKA\nHari ini kita membahas ${topic.toLowerCase()}.\n\nKONTRIBUSI ANDA\n${take}\n\nBUKTI VISUAL\nTampilkan demonstrasi atau bukti yang mendukung penjelasan, bukan sekadar mengulang cuplikan.\n\nPENUTUP\nRingkas hal yang bisa diterapkan dan batasnya. Ajak penonton bertanya tentang bagian yang belum jelas.`};}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a[data-action]');if(!el)return;try{
 if(el.dataset.coachPrompt){const prompts={niche:'Bantu saya memilih 3 niche berdasarkan profil saya. Bandingkan kecocokan, pasar, kesulitan, dan eksperimen murah. Jika profil kurang, tanyakan hal terpenting.',today:'Berdasarkan progres saya, berikan misi hari ini yang realistis sesuai waktu dan anggaran. Jangan ulangi misi yang sudah selesai.',review:'Evaluasi hasil channel dan misi saya berdasarkan metrik yang sudah dicatat. Apa keputusan berikutnya dan apa yang belum bisa disimpulkan?',stuck:'Saya sedang buntu. Bantu temukan hambatan utama, tanyakan hal yang paling penting dan berikan satu langkah kecil untuk hari ini.'};el.disabled=true;return await sendCoach(prompts[el.dataset.coachPrompt]);}
 if(el.dataset.coachNiche!==undefined){const n=state('coachNiches',[])[Number(el.dataset.coachNiche)];await save('profile',{...state('profile',{}),niche:n.name});await refresh();render();return toast('Niche dipilih: '+n.name);}
 if(el.dataset.nav)return navigate(el.dataset.nav);
 if(el.dataset.openMedia){selected=el.dataset.openMedia;subtab='edit';return navigate('studio');}
 if(el.dataset.studioTab){subtab=el.dataset.studioTab;return render();}
 if(el.dataset.pickNiche){await save('profile',{...state('profile',{}),niche:el.dataset.pickNiche});await refresh();render();return toast('Niche dipilih. Lengkapi rencana di Mentor channel.');}
 if(el.dataset.candidate!==undefined){const c=state('transcript:'+selected,{candidates:[]}).candidates[Number(el.dataset.candidate)];subtab='edit';render();$('#render-form [name=start]').value=c.start;$('#render-form [name=end]').value=c.end;if($('#preview'))$('#preview').currentTime=c.start;else if($('#yt-preview'))$('#yt-preview').src='https://www.youtube-nocookie.com/embed/'+state('youtube:'+selected,{}).video_id+'?start='+Math.floor(c.start)+'&end='+Math.ceil(c.end);return;}
 if(el.dataset.editSource)return sourceForm(el.dataset.editSource);
 if(el.dataset.editCalendar)return calendarForm(el.dataset.editCalendar);
 if(el.dataset.editMetric)return metricForm(el.dataset.editMetric);
 for(const [attr,key] of [['deleteSource','sources'],['deleteCalendar','calendar'],['deleteMetric','metrics']])if(el.dataset[attr]){if(!confirm('Hapus catatan ini?'))return;await save(key,state(key,[]).filter(x=>x.id!==el.dataset[attr]));$('#modal').close();render();return;}
 if(el.dataset.deleteMedia){if(!confirm('Hapus media sumber ini? Hasil ekspor tetap tersimpan.'))return;await api('delete-media',{id:el.dataset.deleteMedia});if(selected===el.dataset.deleteMedia)selected=null;await refresh();render();return;}
 if(el.dataset.publish){await save('calendar',state('calendar',[]).map(c=>c.id===el.dataset.publish?{...c,status:'published'}:c));return render();}
 const a=el.dataset.action;if(!a)return;
 if(a.startsWith('go-'))return navigate(a.slice(3));
 if(a==='menu')return $('.sidebar')?.classList.toggle('open');
 if(a==='close-modal')return $('#modal').close();
 if(a==='new-source')return sourceForm();
 if(a==='new-calendar')return calendarForm();
 if(a==='new-metric')return metricForm();
 if(a==='open-subtitles'){subtab='subtitles';return render();}
 if(a==='logout'){await api('logout',{});return login();}
 if(a==='analyze'){el.disabled=true;const r=await api('analyze',{media:selected});await refresh();render();watchJob(r.job);return;}
 if(a==='youtube-refresh'){el.disabled=true;const r=await api('youtube',{url:state('youtube:'+selected,{}).url,language:state('profile',{}).language||'id'});await refresh();render();watchJob(r.job);return;}
 if(a==='youtube-video'){if(!$('#youtube-rights')?.checked)return toast('Konfirmasikan hak penggunaan terlebih dahulu.');el.disabled=true;const r=await api('youtube-video',{media:selected,rights:true});await refresh();render();watchJob(r.job);return;}
 if(a==='full-srt'||a==='range-srt'){const f=$('#render-form'),start=a==='range-srt'?Number(f.elements.start.value):0,end=a==='range-srt'?Number(f.elements.end.value):Infinity;if(!(end>start))return toast('Rentang waktu tidak valid.');const text=subtitleFile(state('transcript:'+selected,{segments:[]}).segments,start,end);if(!text)return toast('Tidak ada subtitle dalam rentang ini.');return download('viraclip-subtitle.srt',text,'text/plain');}
 if(a==='preview-range'&&$('#yt-preview')){const f=$('#render-form'),start=Number(f.elements.start.value),end=Number(f.elements.end.value);if(!(end>start))return toast('Rentang tidak valid.');$('#yt-preview').src='https://www.youtube-nocookie.com/embed/'+state('youtube:'+selected,{}).video_id+'?start='+Math.floor(start)+'&end='+Math.ceil(end);return;}
 if(a==='preview-range'){const v=$('#preview'),f=$('#render-form'),start=Number(f.elements.start.value),end=Number(f.elements.end.value);if(!(end>start))return toast('Waktu selesai harus setelah mulai.');v.currentTime=start;v.ontimeupdate=()=>{if(v.currentTime>=end){v.pause();v.ontimeupdate=null}};await v.play();return;}
 if(a==='transcribe'){if(!data.capabilities.transcription)return toast('Mesin transkripsi belum tersedia. Gunakan impor SRT.');el.disabled=true;const r=await api('transcribe',{media:selected,language:state('profile',{}).language||'id'});await refresh();render();watchJob(r.job);return toast('Transkripsi masuk antrean.');}
 if(a==='import-srt'){modal('Impor subtitle SRT',`<form id="srt-form"><p class="sub">Waktu subtitle mengikuti video sumber, sebelum pemotongan.</p><label class="field">Pilih file SRT<input type="file" id="srt-file" accept=".srt,text/plain"></label>${area('Atau tempel isi subtitle','srt','','required placeholder="1\n00:00:00,000 --> 00:00:03,000\nTeks subtitle"')}<button class="primary" type="submit">Simpan subtitle</button></form>`);return;}
 if(a==='save-subtitles'){const old=state('transcript:'+selected,{segments:[]});const segments=old.segments.map((s,i)=>({...s,text:$(`[data-subtitle="${i}"]`)?.value??s.text}));const r=await api('subtitles',{media:selected,segments});data.state['transcript:'+selected]=r;return toast('Koreksi subtitle disimpan.');}
 if(a==='backup'){const b=await api('backup');download('viraclip-cadangan-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(b,null,2),'application/json');return;}
 if(a==='copy-draft'){const text=$('#draft-text').value;try{await navigator.clipboard.writeText(text);toast('Draf disalin.')}catch{$('#draft-text').select();toast('Pilih salin dari menu browser.')}return;}
 if(a==='draft-calendar'){const text=$('#draft-text').value;$('#modal').close();calendarForm();$('#calendar-form [name=description]').value=text;$('#calendar-form [name=title]').value=window.latestPack?.titles[0]||'';return;}
 }catch(err){toast(err.message);el.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='upload')return await upload(el.files[0]);
 if(el.id==='srt-file'){if(el.files[0])$('#srt-form [name=srt]').value=await el.files[0].text();return;}
 if(el.dataset.coachTask){await save('coachTasks',{...state('coachTasks',{}),[el.dataset.coachTask]:el.checked});render();return;}
 if(el.dataset.task){await save('tasks',{...state('tasks',{}),[el.dataset.task]:el.checked});render();return;}
 if(el.dataset.check){await save('checklist',{...state('checklist',{}),[el.dataset.check]:el.checked});toast('Daftar periksa disimpan.');}
 }catch(err){toast(err.message);if(el.id==='upload'){el.disabled=false;if($('#upload-status'))$('#upload-status').textContent='Unggahan gagal. Pilih berkas untuk mencoba lagi.';}if(el.type==='checkbox')el.checked=!el.checked;}});
document.addEventListener('input',e=>{if(e.target.name==='position'&&$('#position-label'))$('#position-label').textContent=e.target.value+'%';if(e.target.closest('#calculator')){const n=x=>Math.max(0,Number($(`[name=${x}]`).value)||0);$('#calc-result').textContent=money(n('calcviews')/1000*n('calcrpm')-n('calccost'))+' setelah biaya';}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),submit=f.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{
 if(f.id==='login-form'){await api('login',b);await refresh();route=location.hash.slice(1)||'dashboard';if(!views[route])route='dashboard';render();data.jobs.filter(j=>['queued','running'].includes(j.status)).forEach(j=>watchJob(j.id));return;}
 if(f.id==='youtube-form'){const r=await api('youtube',b);await refresh();render();watchJob(r.job);return toast('Pengambilan caption masuk antrean.');}
 if(f.id==='attach-form'){const r=await api('attach-video',{source:selected,target:b.target});selected=r.media;await refresh();render();return toast('Transkrip dihubungkan. Periksa sinkronisasi sebelum ekspor.');}
 if(f.id==='coach-form'){return await sendCoach(b.message);}
 if(f.id==='profile-form'){await save('profile',b);await save('tasks',{...state('tasks',{}),profile:true});await refresh();render();return toast('Rencana diperbarui berdasarkan profil Anda.');}
 if(f.id==='source-form')return await saveList('sources',f,{checkedAt:new Date().toISOString()});
 if(f.id==='calendar-form')return await saveList('calendar',f);
 if(f.id==='metric-form')return await saveList('metrics',f);
 if(f.id==='monetization-form'){await save('monetization',{...b,updated:Date.now()});render();return toast('Perkembangan disimpan.');}
 if(f.id==='password-form'){await api('password',b);toast('Kata sandi diperbarui. Silakan masuk kembali.');return login();}
 if(f.id==='srt-form'){const r=await api('subtitles',{media:selected,srt:b.srt});data.state['transcript:'+selected]=r;$('#modal').close();render();return toast('Subtitle berhasil diimpor.');}
 if(f.id==='render-form'){const r=await api('render',{...b,start:Number(b.start),end:Number(b.end),position:Number(b.position),subtitles:!!b.subtitles,media:selected});await refresh();render();watchJob(r.job);return toast('Ekspor masuk antrean.');}
 if(f.id==='copy-form'){const pack=copyPack(b);window.latestPack=pack;const text='PILIHAN JUDUL\n'+pack.titles.map((x,i)=>`${i+1}. ${x}`).join('\n')+'\n\nDESKRIPSI\n'+pack.description+'\n\nRANCANGAN NARASI\n'+pack.script;await save('drafts',[{id:uid(),created:Date.now(),...pack},...state('drafts',[])].slice(0,50));modal('Draf publikasi',`<p class="sub">Periksa fakta dan sesuaikan dengan video akhir. Hashtag membantu konteks; tidak ada jaminan distribusi atau viralitas.</p><textarea id="draft-text" style="min-height:350px">${esc(text)}</textarea><div class="row section-space">${btn('Salin draf','copy-draft')}${btn('Jadikan agenda','draft-calendar','ghost')}</div>`);return;}
 }catch(err){if(f.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);if(views[name]&&name!==route){route=name;if($('.layout'))render();}});
(async()=>{try{research=await (await fetch('/research.json')).json();const s=await api('session');if(!s.authenticated)return login();await refresh();route=location.hash.slice(1)||'dashboard';if(!views[route])route='dashboard';render();data.jobs.filter(j=>['queued','running'].includes(j.status)).forEach(j=>watchJob(j.id));}catch(e){$('#app').innerHTML=`<div class="login"><h1>Workspace belum terhubung</h1><p>${esc(e.message)}</p><a href="/">Muat ulang halaman</a></div>`;}})();
